INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7510216, 1198191, 136989, '<td valign="top">Greetings from the Critique Club!<br/>I''m not sure laying in cold water for hours is something that would make me happy but catching this image certainly would.  It''s so much fun to watch birds as they hunt, so I can see how this makes you happy and meets the challenge.  :)  I love how the coolness of the water comes through and balances with the warmth of the yellows and browns in the background and on the heron. Great focus on the heron to capture the feather details.  The clarity of the bird with a soft-focused fore and background definitely works. The perspective is also great.  Laying in that water paid off!  I wish I had some constructive advice to offer here but I''m stumped ... I mean, shoot ... you can see the eyes on the fish!  How can I argue with that?!</td>', 'Greetings from the Critique Club!I''m not sure laying in cold water for hours is something that would make me happy but catching this image certainly would.  It''s so much fun to watch birds as they hunt, so I can see how this makes you happy and meets the challenge.  :)  I love how the coolness of the water comes through and balances with the warmth of the yellows and browns in the background and on the heron. Great focus on the heron to capture the feather details.  The clarity of the bird with a soft-focused fore and background definitely works. The perspective is also great.  Laying in that water paid off!  I wish I had some constructive advice to offer here but I''m stumped ... I mean, shoot ... you can see the eyes on the fish!  How can I argue with that?!', '2017-04-21 15:31:22.000000', NULL, 0),
(7510437, 1198185, 136989, '<td valign="top">Greetings from the Critique Club!<br/>Challenge: How can you go wrong in meeting a challenge when it''s all about you?  :)  I love that your subject is a beautiful female cardinal.  They don''t get enough attention compared to their flamboyant other halves.<br/> <br/>Composition, Focus, Etc.: Love the pastel colors with the natural background that really makes them pop.  Focus on the face/eye and closest foot is great.  The far away look/reflection in the eye adds depth and a bit of wonder.  (i.e., What is she looking at anyway?) Nice feather details and framing. From what I think is a little water droplet below the beak it seems to be raining ... the lines sporadically in the background reinforce this.  I''m trying to decide if they help or hurt.  Maybe if there were a few more it would be any easier call. But then again we go back to depth and what makes *you* happy.</td>', 'Greetings from the Critique Club!Challenge: How can you go wrong in meeting a challenge when it''s all about you?  :)  I love that your subject is a beautiful female cardinal.  They don''t get enough attention compared to their flamboyant other halves. Composition, Focus, Etc.: Love the pastel colors with the natural background that really makes them pop.  Focus on the face/eye and closest foot is great.  The far away look/reflection in the eye adds depth and a bit of wonder.  (i.e., What is she looking at anyway?) Nice feather details and framing. From what I think is a little water droplet below the beak it seems to be raining ... the lines sporadically in the background reinforce this.  I''m trying to decide if they help or hurt.  Maybe if there were a few more it would be any easier call. But then again we go back to depth and what makes *you* happy.', '2017-04-23 13:33:19.000000', NULL, 0),
(7514599, 1198192, 68504, '<td valign="top">gorgeous. how rarely do we get to touch anything like this.</td>', 'gorgeous. how rarely do we get to touch anything like this.', '2017-05-19 03:26:49.000000', NULL, 0),
